// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface WorklistItemOut {
  lab_requisition_item_id: number;
  requisition_id: number;
  requisition_number: string;
  priority: "Routine" | "Urgent" | "STAT";
  ordered_at: string;
  status: "Ordered" | "SampleCollected" | "Processing" | "PendingVerification" | "Published" | "ReRunRequired" | "Cancelled";
  code: string;
  test_name: string;
  sample_id: number | null;
  barcode: string | null;
  sample_status: "Pending" | "Collected" | "Received" | "Dispatched" | "Rejected" | "Consumed" | null;
  patient_name: string;
  mrn: string;
  is_lab_only_walkin: boolean;
  is_inpatient: boolean;
  /** Urgent or STAT: the emergency turnaround (MSDS AAC 4: every one on time) */
  is_emergency: boolean;
  /** Goes to a partner laboratory (GET /lab/send-outs/pending) */
  is_send_out: boolean;
  /** When the result is due (null until the sample is received) */
  due_at: string | null;
  is_overdue: boolean;
}

/** How the patient is identified before a sample is taken or an examination starts (MSDS AAC 3, 10, 30). */
export interface IdentityIn {
  /** What the scanner read from the wristband (the MRN, or HMS:PT:<mrn>) */
  wristband_code?: string | null;
  /** Without a scan: TwoIdentifiers (name and date of birth or MRN asked), or EmergencyOverride (an emergency patient who cannot be identified yet; identity_note required) */
  identity_check?: "WristbandScan" | "TwoIdentifiers" | "EmergencyOverride" | null;
  identity_note?: string | null;
}

