/** Open lab work (STAT first) — GET /api/v1/lab/worklist (who may call: holders of lab.sample.collect or lab.sample.receive or lab.result.enter). */
export function worklistLab(query?: { status?: "Ordered" | "SampleCollected" | "Processing" | "PendingVerification" | null }): Promise<WorklistItemOut[]> {
  return api<WorklistItemOut[]>("GET", withQuery(`/lab/worklist`, query), undefined);
}

/** Collect a sample → returns the barcode label print payload — POST /api/v1/lab/samples/{sample_id}/collect (who may call: holders of lab.sample.collect). */
export function collectLabSamples(sample_id: number, body: IdentityIn): Promise<PrintOut_LabLabelFieldsOut_> {
  return api<PrintOut_LabLabelFieldsOut_>("POST", `/lab/samples/${sample_id}/collect`, body);
}

/** Re-print a sample barcode label — GET /api/v1/lab/samples/{sample_id}/label (who may call: holders of lab.sample.collect). */
export function label(sample_id: number): Promise<PrintOut_LabLabelFieldsOut_> {
  return api<PrintOut_LabLabelFieldsOut_>("GET", `/lab/samples/${sample_id}/label`, undefined);
}

/** Scanner lookup → metric grid with this patient's reference ranges — GET /api/v1/lab/scan/{barcode} (who may call: holders of lab.sample.receive or lab.result.enter). */
export function scanLab(barcode: string): Promise<LabScanOut> {
  return api<LabScanOut>("GET", `/lab/scan/${barcode}`, undefined);
}

/** Mark the sample received in the lab (item → Processing) — POST /api/v1/lab/samples/{sample_id}/receive (who may call: holders of lab.sample.receive). */
export function receiveLabSamples(sample_id: number, body: IdentityIn | null): Promise<LabSampleOut> {
  return api<LabSampleOut>("POST", `/lab/samples/${sample_id}/receive`, body);
}

/** Submit & Broadcast a result (goes to the verifier) — POST /api/v1/lab/items/{item_id}/results (who may call: holders of lab.result.enter). */
export function submitResult(item_id: number, body: ResultIn): Promise<LabResultOut> {
  return api<LabResultOut>("POST", `/lab/items/${item_id}/results`, body);
}

/** Re-run a failed test (new barcode, not billed again) — POST /api/v1/lab/items/{item_id}/rerun (who may call: holders of lab.rerun.request). */
export function rerun(item_id: number, body: LabReasonIn): Promise<LabRequisitionDetailOut> {
  return api<LabRequisitionDetailOut>("POST", `/lab/items/${item_id}/rerun`, body, { idempotent: true });
}

/** Amend a published result (re-verification required) — POST /api/v1/lab/items/{item_id}/corrections (who may call: holders of lab.result.enter). */
export function correctResult(item_id: number, body: ResultCorrectionIn): Promise<LabResultOut> {
  return api<LabResultOut>("POST", `/lab/items/${item_id}/corrections`, body, { idempotent: true });
}

/** Reject an unusable sample (the test goes back to collection) — POST /api/v1/lab/samples/{sample_id}/reject (who may call: holders of lab.sample.receive or lab.sendout.manage). */
export function rejectSample(sample_id: number, body: SampleRejectIn): Promise<LabRequisitionDetailOut> {
  return api<LabRequisitionDetailOut>("POST", `/lab/samples/${sample_id}/reject`, body, { idempotent: true });
}

/** Scan to verify a patient's identity — GET /api/v1/wristbands/verify (who may call: holders of patient.view). */
export function verifyWristband(query: { code: string; admission_id?: number | null; er_visit_id?: number | null; patient_id?: number | null }): Promise<IdentityVerifyOut> {
  return api<IdentityVerifyOut>("GET", withQuery(`/wristbands/verify`, query), undefined);
}
